  "여사건으로 적어도 하나가 나올 확률 구하기": [
    "Find the probability of at least one occurrence of a given event",
    "求给定事件至少发生一次的概率"
  ],
  "주머니에 빨간 구슬 4개, 파란 구슬 3개, 초록 구슬 2개가 있습니다. 구슬 2개를 되돌려 놓지 않고 꺼낼 때 빨간 구슬이 적어도 하나 나올 확률은 얼마인가요?": [
    "In the pocket there are 4 red beads, 3 blue beads, and 2 green beads. What is the probability that at least one red marble will come out when the marble 2 is taken out rather than put back?",
    "口袋里有 4 红色珠子、 3 蓝色珠子和 2 绿色珠子。当取出而不是放回弹珠 2 时，至少出现一颗红色弹珠的概率是多少？"
  ],
  "빨간 구슬이 하나도 나오지 않는 경우를 먼저 구해 전체 확률에서 빼요.": [
    "First find the case in which no red marbles appear and subtract it from the total probability.",
    "首先找到没有出现红色弹珠的情况，并将其从总概率中减去。"
  ],
  "전체 구슬은 9개이고 빨간색이 아닌 구슬은 5개입니다.": [
    "There are 9 marbles in total and 5 marbles that are not red.",
    "共有 9 个弹珠，其中 5 个弹珠不是红色的。"
  ],
  "빨간 구슬이 하나도 안 나올 확률은 첫 번째가 빨간색 아님일 확률 5/9에, 두 번째도 빨간색 아님일 확률 4/8을 곱한 5/18입니다.": [
    "The probability of not getting a single red marble is 5/18, which is the probability of the first marble not being red multiplied by 5/9 and the probability of the second marble being not red multiplied by 4/8.",
    "没有得到红色弹珠的概率是 5/18，即第一个弹珠不是红色的概率乘以 5/9，第二个弹珠不是红色的概率乘以 4/8。"
  ],
  "적어도 하나 빨간 구슬이 나올 확률은 1−5/18=13/18입니다.": [
    "The probability of getting at least one red marble is 1−5/18=13/18.",
    "获得至少一颗红色弹珠的概率为 1−5/18=13/18。"
  ],
  "구슬을 한 번 꺼낸 뒤 되돌려 놓으면 여사건의 확률 계산이 어떻게 달라지나요?": [
    "How does the probability calculation of the female case change if you take out the marble once and then return it?",
    "如果你取出弹珠一次然后将其归还，女性情况的概率计算会如何变化？"
  ],
