  "12명": [
    "12 people",
    "12人"
  ],
  "전체는 10+18+12=40명입니다. 7학년은 18명이므로 18÷40=0.45=45%입니다.": [
    "The total is 10 + 18 + 12 = 40 people.  Since 7 grades are 18 people, 18 ÷ 40 = 0.45 = 45 %.",
    "总数为 10 + 18 + 12 = 40 人。  由于 7 年级为 18 人，因此 18 ÷ 40 = 0.45 = 45 %。"
  ],
  "배수의 합집합": [
    "union of multiples",
    "倍数的并集"
  ],
  "1부터 100까지의 정수 중 3 또는 5의 배수는 몇 개인가요?": [
    "How many integers from 1 to 100 are multiples of 3 or 5?",
    "1到100之间有多少个整数是3或5的倍数？"
  ],
  "3의 배수는 33개, 5의 배수는 20개입니다. 두 번 센 15의 배수 6개를 빼면 33+20−6=47개입니다.": [
    "There are 33 multiples of 3 and 20 multiples of 5. Subtract 6 multiples of 15 counted twice and you get 33+20−6=47.",
    "3的倍数有33个，5的倍数有20个。减去两次数的6个15的倍数，得到33+20−6=47。"
  ],
  "둘레 조건을 식으로 연결하기": [
    "Connecting the perimeter conditions to equations",
    "将周长条件连接到方程"
  ],
  "직사각형의 긴 변은 짧은 변보다 7cm 더 깁니다. 둘레가 62cm라면 짧은 변은 몇 cm인가요?": [
    "The long side of the rectangle is 7 cm longer than the short side. If the circumference is 62cm, how many cm is the short side?",
    "长方形的长边比短边长7厘米。如果周长是62厘米，那么短边是多少厘米？"
  ],
  "짧은 변을 w라 하면 긴 변은 w+7입니다. 둘레 조건에서 2(w+w+7)=62, 따라서 2w+7=31이고 w=12cm입니다.": [
    "If the short side is w, the long side is w+7. In terms of perimeter, 2(w+w+7)=62, so 2w+7=31 and w=12cm.",
    "如果短边为w，则长边为w+7。就周长而言，2(w+w+7)=62，所以2w+7=31，w=12cm。"
  ],
  "넓이 관계로 나머지 영역 찾기": [
    "Find remaining area based on area",
    "根据面积求剩余面积"
  ],
  "한 변이 12cm인 정사각형을 세로선 하나와 가로선 하나로 네 직사각형으로 나눕니다. 왼쪽 위, 오른쪽 위, 왼쪽 아래 직사각형의 넓이가 각각 16cm², 32cm², 32cm²입니다. 오른쪽 아래 직사각형의 넓이는 얼마인가요?": [
    "Divide a square with a side of 12 cm into four rectangles with one vertical line and one horizontal line. The areas of the upper left, upper right, and lower left rectangles are 16cm², 32cm², and 32cm², respectively. What is the area of ​​the lower right rectangle?",
    "将边长为 12 厘米的正方形分成四个长方形，各有一条竖线和一条横线。左上、右上、左下矩形的面积分别为16cm²、32cm²、32cm²。右下长方形的面积是多少？"
  ],
  "주어진 넓이에서 가로 길이는 4cm와 8cm로 나뉘고, 세로 길이도 4cm와 8cm로 나뉩니다. 따라서 오른쪽 아래 넓이는 8×8=64cm²입니다.": [
    "For a given area, the horizontal length is divided into 4cm and 8cm, and the vertical length is also divided into 4cm and 8cm. Therefore, the area in the lower right is 8×8=64cm².",
    "对于给定的面积，水平长度分为4cm和8cm，垂直长度也分为4cm和8cm。因此，右下面积为8×8=64cm²。"
  ],
  "격자에서 직사각형 세기": [
    "Counting Rectangles in a Grid",
    "计算网格中的矩形"
  ],
  "단위 정사각형 3행 4열로 된 격자에서 격자선을 변으로 하는 직사각형은 모두 몇 개인가요? 정사각형도 포함합니다.": [
    "In a grid with 3 rows and 4 columns of unit squares, how many rectangles have grid lines as sides? Also includes squares.",
    "在一个 3 行 4 列单位正方形的网格中，有多少个以网格线为边的矩形？还包括正方形。"
  ],
  "세로 격자선 5개 중 2개를 고르는 방법은 10가지, 가로 격자선 4개 중 2개를 고르는 방법은 6가지입니다. 10×6=60개의 직사각형입니다.": [
    "There are 10 ways to select 2 out of 5 vertical grid lines and 6 ways to select 2 out of 4 horizontal grid lines. 10×6=60 rectangles.",
    "有 10 种方法可以从 5 条垂直网格线中选择 2 条，有 6 种方法可以从 4 条水平网格线中选择 2 条。 10×6=60个矩形。"
  ],
  "최소공배수와 나머지 연결하기": [
    "Connect least common multiple and remainder",
    "连接最小公倍数和余数"
  ],
  "2, 3, 4, 5로 각각 나누면 나머지가 그 수보다 1 작고, 7의 배수인 가장 작은 양의 정수는 무엇인가요?": [
    "When divided by 2, 3, 4, and 5, what is the smallest positive integer whose remainder is 1 less than that number and is a multiple of 7?",
    "除以 2、3、4、5 时，余数比该数少 1 并且是 7 的倍数的最小正整数是多少？"
  ],
  "찾는 수에 1을 더하면 2, 3, 4, 5의 공배수이므로 60의 배수에서 1을 뺀 수입니다. 59는 7의 배수가 아니고, 다음 후보 119=7×17이므로 답은 119입니다.": [
    "If you add 1 to the number you are looking for, it is a common multiple of 2, 3, 4, and 5, so it is a multiple of 60 minus 1. 59 is not a multiple of 7, and the next candidate is 119=7×17, so the answer is 119.",
    "如果你要找的数字加1，它是2、3、4、5的公倍数，所以是60减1的倍数。59不是7的倍数，下一个候选是119=7×17，所以答案是119。"
  ],
