  "원자료 보고서 ↗": [
    "Raw data report ↗",
    "原始数据报告↗"
  ],
  "학교가 공개한 전국 학년별 통계의 재인용입니다. MAA 원본 보고서 파일을 확보하지 못했습니다. 이 표본 평균은 현재 기준점·백분위·능력 등급이 아닙니다.": [
    "This is a requote of national statistics by grade released by the school. The MAA original report file could not be obtained. This sample mean is not currently a cutoff point, percentile, or proficiency rating.",
    "这是学校发布的按年级划分的全国统计数据的重新报价。无法获取 MAA 原始报告文件。该样本均值当前不是截止点、百分位数或熟练程度评级。"
  ],
  "99CEF 분석 보고서의 미국·캐나다 참가자 집계입니다. 세계 참가자 통계와 서로 다른 모집단이므로 연도별 추세로 직접 비교하지 않습니다. 해당 회차·기록 학년의 과거 평균일 뿐 백분위·현재 규준·능력 등급이 아닙니다.": [
    "This is a tally of US and Canadian participants in the 99CEF analysis report. Because they are different populations from global participant statistics, year-to-year trends are not directly comparable. It is only a past average for the relevant session/recorded grade and is not a percentile, current standard, or ability level.",
    "这是 99CEF 分析报告中对美国和加拿大参与者的统计。由于它们是来自全球参与者统计数据的不同人群，因此逐年趋势无法直接比较。它只是相关课程/记录成绩的过去平均值，而不是百分位、当前标准或能力水平。"
  ],
  "99CEF 분석 보고서의 세계 참가자 집계이며 미국 단독 모집단은 아닙니다. 해당 연도·시험형·기록 학년의 과거 평균만 비교합니다. 백분위·현재 규준·능력 등급이 아닙니다.": [
    "This is a global count of participants in the 99CEF analysis report and is not the U.S.-only population. Only the past averages for the relevant year, test type, and recorded grade are compared. It is not a percentile, current standard, or ability level.",
    "这是 99CEF 分析报告中的全球参与者人数，并非仅限美国人口。仅比较相关年份、考试类型和记录成绩的过去平均值。它不是百分位、当前标准或能力水平。"
  ],
  "포럼에 전사된 MAA 학년 평균표입니다. 표의 Location은 United States이며 MAA 원본 보고서는 회수하지 못했습니다. 미국 응시집단의 당시 평균 비교이며 전국 전체·백분위·현재 능력 등급이 아닙니다.": [
    "This is the MAA grade average table transcribed in the forum. The Location in the table is United States and the original MAA report has not been recovered. This is a comparison of the average of the U.S. test-taking group at the time and is not a national overall, percentile, or current ability level.",
    "这是论坛上抄录的MAA平均成绩表。表中的位置是美国，原始 MAA 报告尚未恢复。这是对当时美国应试群体平均水平的比较，并非全国总体、百分位数或当前能力水平。"
  ],
  "재게시된 MAA 학년·성별 평균표 이미지에서 전사한 과거 통계입니다. Location 표기와 지리적 모집단은 원 이미지에 명시된 범위만 적용합니다. 해당 연도·기록 학년의 평균이며 백분위·현재 규준·능력 등급이 아닙니다.": [
    "These are past statistics transcribed from the reposted MAA grade/gender average table image. Location notation and geographic population only apply to the range specified in the original image. This is the average for the year/recorded grade and is not a percentile, current norm, or proficiency level.",
    "这些是从重新发布的 MAA 成绩/性别平均表图像转录的过去统计数据。位置符号和地理人口仅适用于原始图像中指定的范围。这是当年/记录成绩的平均值，不是百分位数、当前标准或熟练程度。"
  ],
  "GEMT 연례 분석 보고서의 웹 검색 색인 텍스트에서 옮긴 세계 참가자 통계입니다. PDF 페이지 이미지를 직접 대조하지 못했으며 원문 색인 전사 수준으로 표시합니다. 같은 연도·시험형·기록 학년의 과거 평균이며 백분위·현재 규준·능력 등급이 아닙니다.": [
    "World participant statistics transcribed from web-searchable index text of GEMT Annual Analysis Report. PDF page images cannot be directly collated and are displayed at the full-text index transcription level. It is a historical average for the same year, test type, and recorded grade, and is not a percentile, current standard, or ability level.",
    "世界参与者统计数据转录自 GEMT 年度分析报告的网络可搜索索引文本。 PDF页面图像无法直接整理，并以全文索引转录级别显示。它是同一年份、测试类型和记录成绩的历史平均值，而不是百分位、当前标准或能力水平。"
  ],
  "GEMT 보고서에 직접 실린 대만 지역 참가자 통계입니다. Grade 7 표본은 19명으로 작습니다. 세계 또는 미국 학년 기준과 섞지 않으며, 백분위·현재 규준·능력 등급이 아닙니다.": [
    "These are Taiwanese participant statistics directly included in the GEMT report. The Grade 7 sample is small, with 19 students. It is not mixed with global or U.S. grade standards and is not a percentile, current norm, or proficiency level.",
    "这些是GEMT报告中直接包含的台湾参与者统计数据。 7 年级样本较小，有 19 名学生。它不与全球或美国年级标准混合，也不是百分位数、当前标准或熟练程度。"
  ],
  "같은 연도·시험형·기록 학년이 확인되는 과거 응시 집단 평균입니다. 현재 기준점이나 능력 등급이 아니며, 다른 연도·시험형으로 비교하지 않습니다. 표본과 범위는 연결된 출처 기준입니다.": [
    "This is the average of past test-taking groups for which the same year, test type, and record grade are confirmed. It is not a current reference point or ability level, and is not compared across different years or test types. Sample and range are based on linked sources.",
    "这是已确认的同一年份、考试类型和记录成绩的过去应试组的平均值。它不是当前的参考点或能力水平，并且不会在不同年份或测试类型之间进行比较。样本和范围基于链接来源。"
  ],
