  "입력 점수 __GFIELD_0____GFIELD_1__점 · 한국 해당 학년 평균보다 __GFIELD_2__": [
    "Input score __GFIELD_0____GFIELD_1__ points · __GFIELD_2__ above the Korean grade average",
    "输入分数 __GFIELD_0____GFIELD_1__ 分 · __GFIELD_2__ 高于韩国平均成绩"
  ],
  "__GFIELD_0__ 값입니다. 보고된 전체 __GFIELD_1__명 중 학년 표에 __GFIELD_2__명이 기재되어 __GFIELD_3__명은 학년 집계에 포함되지 않았습니다. 현재 규준이나 다른 지역 응시자 비교가 아닙니다.": [
    "The __GFIELD_0__ value. Of the total __GFIELD_1__ students reported, __GFIELD_2__ students were listed in the grade table and __GFIELD_3__ students were not included in the grade count. This is not a comparison of current standards or test takers from other regions.",
    "__GFIELD_0__ 值。在报告的 __GFIELD_1__ 学生总数中，__GFIELD_2__ 学生已列在成绩表中，而 __GFIELD_3__ 学生未包含在成绩统计中。这不是对当前标准或其他地区考生的比较。"
  ],
  "Internet Archive에 보존된 MAA 한국 결과 원문": [
    "Original MAA Korean results preserved in Internet Archive",
    "原始 MAA 韩国结果保存在互联网档案馆中"
  ],
  "한국 응시집단의 과거 결과표": [
    "Past result table of Korean test taker group",
    "韩国考生历届成绩表"
  ],
  "__GFIELD_0__ AMC 8 · __GFIELD_1__ · __GFIELD_2__/25점 · 해당 점수 __GFIELD_3__명 · 학년 표본 __GFIELD_4__명": [
    "__GFIELD_0__ AMC 8 · __GFIELD_1__ · __GFIELD_2__/25 points · Corresponding score __GFIELD_3__ people · Grade sample __GFIELD_4__ people",
    "__GFIELD_0__ AMC 8 · __GFIELD_1__ · __GFIELD_2__/25 分 · 对应分数 __GFIELD_3__ 人 · 年级样本 __GFIELD_4__ 人"
  ],
  "점수보다 낮은 응시자 __GFIELD_0__% · __GFIELD_1__/__GFIELD_2__명": [
    "__GFIELD_0__% of test takers with scores lower than __GFIELD_1__/__GFIELD_2__",
    "__GFIELD_0__% 的考生分数低于 __GFIELD_1__/__GFIELD_2__"
  ],
  "2006 MAA AMC 8 보고서 Table 5의 학년별 점수 빈도입니다. 4–5학년은 원자료의 묶음이며, 국제 학교 참가자도 보고서 모집단에 포함됩니다. 원문은 제3자 보관 사본에서 확인했고 0점의 시도/미시도 구간은 합산했습니다.": [
    "2006 MAA AMC 8 Score frequency by grade in the report Table 5 .  The 4 – 5 grades are a bundle of raw data, and international school participants are also included in the report population. The original text was checked from my 3 archived copy, and the attempted/unattempted intervals of the 0 points were added up.",
    "2006 MAA AMC 8 报告表 5 中按年级划分的评分频率。 4 – 5 成绩是一组原始数据，国际学校参与者也包含在报告人群中。原文是从我的 3 存档副本中检查的，并将 0 点的尝试/未尝试间隔相加。"
  ],
  "2007 MAA 연례 보고서 Table 7의 기록 학년별 점수 분포입니다. 4–5학년은 원자료의 묶음입니다. MAA 원본 보고서의 웹 보관 사본에서 전사했으며 현재 규준이 아닙니다.": [
    "The score distribution by grade is recorded in Table 7 of the 2007 MAA Annual Report. Grades 4–5 are a bundle of source material. This is transcribed from a web archived copy of the MAA original report and is not currently normative.",
    "各年级的分数分布记录在2007年MAA年度报告的表7中。 4-5 年级是一组源材料。这是从 MAA 原始报告的网络存档副本转录的，目前不是规范性的。"
  ],
  "2008 MAA 연례 보고서 Table 7의 기록 학년별 점수 분포입니다. 4–5학년은 원자료의 묶음입니다. MAA 원본 보고서의 웹 보관 사본에서 전사했으며 현재 규준이 아닙니다.": [
    "The score distribution by grade is recorded in Table 7 of the 2008 MAA Annual Report. Grades 4–5 are a bundle of source material. This is transcribed from a web archived copy of the MAA original report and is not currently normative.",
    "2008年MAA年度报告表7记录了各年级的分数分布。 4-5 年级是一组源材料。这是从 MAA 原始报告的网络存档副本转录的，目前不是规范性的。"
  ],
  "2009년 MAA 연례 보고서에 제시된 전체 응시학교의 기록 학년별 점수 분포입니다. 4–5학년은 원자료의 묶음입니다.": [
    "This is the distribution of scores by recorded grade for all participating schools presented in the 2009 MAA Annual Report. Grades 4–5 are a bundle of source material.",
    "这是 2009 年 MAA 年度报告中所有参与学校按记录年级划分的分数分布。 4-5 年级是一组源材料。"
  ],
  "2019 MAA Overall 성적 보고서 이미지의 학년별 점수 빈도입니다. Grade 5 이하는 원자료에서 한 그룹으로 묶인 표본이며, Grade 6–8은 각각 따로 보고됐습니다. 학년 미기록 표본은 학년 비교에서 제외했으며, 그룹별 표본 수와 가중 평균을 보고서 요약과 대조했습니다.": [
    "Score frequency by grade for the 2019 MAA Overall Grade Report image. Grade 5 and below are samples grouped together in the raw data, while grades 6–8 are reported separately. Samples without grade records were excluded from grade comparisons, and sample numbers and weighted averages by group were matched against report summaries.",
    "2019 年 MAA 总体成绩报告图像的按年级评分频率。 5 级及以下是在原始数据中分组的样本，而 6-8 级则单独报告。没有成绩记录的样本被排除在成绩比较之外，样本数量和按组的加权平均值与报告摘要相匹配。"
  ],
  "2022 MAA Overall 점수×학년 보고서 이미지의 전사 자료입니다. Grade 5 이하는 원자료의 묶음이고 Grade 6–8은 각각 따로 보고됐습니다. 학년 미기재 표본은 비교에서 제외했습니다. 그룹별 합계와 점수 0–25의 전체 빈도 합을 이미지와 대조했고, 학년 평균은 별도 MAA Overall 평균표와 소수 둘째 자리까지 일치하는지 확인했습니다. 이미지는 Think Matrix 재게시본입니다.": [
    "This is a transcription of the 2022 MAA Overall Score × Grade Report image. Grades 5 and below are bundles of raw data, while grades 6–8 are reported separately. Samples with no grade specified were excluded from comparison. Group totals and overall frequency sums for scores 0–25 were matched against the images, and grade averages were checked to match the separate MAA Overall averages table to two decimal places. Image is a Think Matrix repost.",
    "这是 2022 年 MAA 总分 × 成绩报告图像的转录。 5 级及以下是原始数据集，而 6-8 级则单独报告。未指定年级的样品被排除在比较之外。分数 0-25 的组总数和总体频率总和与图像进行匹配，并检查成绩平均值以匹配单独的 MAA 总体平均值表，精确到小数点后两位。图片是 Think Matrix 转发的。"
  ],
