  "한 칸짜리 정사각형만 세는 오류": [
    "Error of counting only one-square squares",
    "只计算一格正方形的错误"
  ],
  "전개도에서 종이 위 거리만 보고 마주 보는 면을 고르는 오류": [
    "Error in selecting opposing sides in a developed view based only on the distance on the paper",
    "仅根据纸上的距离在展开视图中选择相对边时出错"
  ],
  "같은 두 사람의 경기를 순서만 바꾸어 두 번 세는 오류": [
    "Error of counting the same two people's matches twice by changing the order",
    "通过改变顺序对相同的两个人的比赛进行两次计数的错误"
  ],
  "겹친 부분을 두 번 빼는 오류": [
    "Error subtracting the overlapped part twice",
    "两次减去重叠部分时出错"
  ],
  "평균을 빠진 수로 바로 고르는 오류": [
    "The error of choosing the average as a missing number",
    "选择平均值作为缺失数的错误"
  ],
  "괄호 안의 한 항에만 3을 곱하는 오류": [
    "Error of multiplying only one term in parentheses by 3",
    "仅将括号中的一项乘以 3 的错误"
  ],
  "1시간에 가는 거리를 먼저 구하지 않고 시간을 곱하는 오류": [
    "The error of multiplying time without first calculating the distance traveled in 1 hour.",
    "未先计算 1 小时内行驶距离而乘以时间的误差。"
  ],
  "가로와 세로를 곱하지 않고 더하는 오류": [
    "Error in adding width and height instead of multiplying them",
    "将宽度和高度相加而不是相乘时出错"
  ],
  "공배수를 두 번 센 채 두 개수를 더하는 오류": [
    "Error of adding two numbers while counting the common multiple twice",
    "计算两次公倍数时将两个数相加的错误"
  ],
  "두 상자의 차이만큼을 먼저 떼어 낸 뒤, 남은 수를 똑같이 나누어 보세요.": [
    "First, separate the difference between the two boxes, then divide the remaining number equally.",
    "首先将两个盒子的差值分开，然后将剩余的数字均分。"
  ],
  "이웃한 두 수 사이의 변화를 차례로 비교하고, 두 단계가 반복되는지 확인해 보세요.": [
    "Compare the changes between two neighboring numbers in turn and see if the two steps are repeated.",
    "依次比较相邻两个数字的变化，看看这两个步骤是否重复。"
  ],
  "9의 배수는 각 자리 숫자의 합도 9의 배수입니다.": [
    "A multiple of 9 is when the sum of each digit is also a multiple of 9.",
    "9的倍数是指各数字之和也是9的倍数。"
  ],
  "큰 직사각형의 넓이에서 잘라 낸 직사각형의 넓이를 빼세요.": [
    "Subtract the area of the cut out rectangle from the area of the larger rectangle.",
    "从较大矩形的面积中减去切出的矩形的面积。"
  ],
  "모든 조건을 ‘누가 누구보다 앞인가’ 화살표로 바꾼 뒤, 누구보다도 뒤에 있지 않은 사람을 찾으세요.": [
    "Change all conditions to ‘who is ahead of whom’ arrows, and then find the person who is not behind anyone else.",
    "将所有条件更改为“谁领先谁”箭头，然后找到不落后于其他人的人。"
  ],
  "두 모임의 수를 더하면 두 모임에 모두 속한 학생이 두 번 세어집니다.": [
    "If you add the numbers of two groups, students who belong to both groups are counted twice.",
    "如果将两个组的人数相加，则属于两个组的学生将被计算两次。"
  ],
  "두 자리 수 AB를 10A+B, BA를 10B+A로 나타내어 관계를 정리하세요.": [
    "Reorganize the relationship by expressing the two-digit number AB as 10A+B and BA as 10B+A.",
    "重组关系，将两位数AB表示为10A+B，将BA表示为10B+A。"
  ],
  "비의 전체 몫 수를 먼저 구하고, 전체 수를 그 몫 수로 나누어 한 몫의 크기를 찾으세요.": [
    "First find the total number of quotients of the ratio, then divide the total number by the number of quotients to find the size of one quotient.",
    "首先求出该比率的商总数，然后将总数除以商数，即可得出一个商的大小。"
  ],
  "직사각형 하나는 서로 다른 세로선 두 개와 가로선 두 개를 고르면 정해집니다.": [
    "A rectangle is created by choosing two different vertical and two horizontal lines.",
    "通过选择两条不同的垂直线和两条水平线来创建矩形。"
  ],
  "정확히 두 면이 칠해진 작은 정육면체는 큰 정육면체의 모서리에 있지만 꼭짓점에는 없습니다.": [
    "The small cube, with exactly two faces painted, is at the corners of the larger cube, but not at its vertices.",
    "小立方体恰好有两个面被绘制，位于大立方体的角上，但不在其顶点处。"
  ],
  "주어진 조건과 구하려는 것을 표시하고, 둘을 잇는 관계를 한 줄로 적어 보세요.": [
    "Indicate the given conditions and what you are looking for, and write the relationship connecting the two in one line.",
    "指出给定的条件和您要寻找的内容，并将两者之间的关系写在一行中。"
  ],
