    "Square ABCD has a side of 10. Let A(0, 0), B(10, 0), C(10, 10), D(0, 10), and take the point P with AP = 2 on AB and the point Q with BQ = 3 on BC. What is the area of ​​triangle DPQ?",
    "正方形 ABCD 的边长为 10。设 A(0, 0)、B(10, 0)、C(10, 10)、D(0, 10)，并在 AB 上取 AP = 2 的点 P，在 BC 上取 BQ = 3 的点 Q。三角形DPQ的面积是多少？"
