  "학년이나 대회를 바꾸면 표시한 내용이 지워집니다.": [
    "If you change the grade or competition, the marked content will be erased.",
    "如果更改成绩或比赛，标记的内容将被删除。"
  ],
  "AMC는 A–E, AIME는 0–999 정수로 답을 입력하세요. 정답표 대조를 누르면 해당 회차의 공개 답안 키로 자동 채점하고, 빈칸은 미응답 처리합니다. 풀이 영역과 오답 이유는 결과 화면에서 직접 조정할 수 있어요.": [
    "Enter your answers as integers A–E for AMC or 0–999 for AIME. When you click on the answer sheet comparison, the answer is automatically graded using the public answer key for that session, and blank spaces are treated as non-answers. The solution area and reasons for incorrect answers can be adjusted directly on the results screen.",
    "输入您的答案为整数 A-E（对于 AMC）或 0-999（对于 AIME）。当您单击答题纸比较时，系统会使用该会话的公共答案码自动对答案进行评分，并且空格将被视为非答案。解答范围和错误答案的原因可以直接在结果屏幕上调整。"
  ],
