  "같은 연도·회차 참고 점수 기준": [
    "Based on reference scores for the same year and session",
    "基于同年同届的参考分数"
  ],
  "MAA K–12 공개 보고서 표본의 같은 연도·시험지 기준점입니다. 동점자가 있을 수 있어 개인의 정확한 백분위가 아니며, 응시 학년별 순위·등급이나 공식 자격 판정이 아닙니다. 다른 연도·회차와 직접 비교하지 마세요.": [
    "Same year/paper cutoff for the MAA K–12 public report sample. Because there may be a tie, it is not an individual's exact percentile, and it is not a ranking or grade by grade or official qualification determination. Do not compare directly with other years or rounds.",
    "MAA K-12 公开报告样本的同年/论文截止日期。因为可能存在平局，所以它不是个人的确切百分位数，也不是按年级或官方资格确定的排名或年级。不要直接与其他年份或轮次进行比较。"
  ],
  "과거 AMC 8 전체 응시자 수상 기준선": [
    "Past AMC 8 All Candidate Award Baselines",
    "过去的 AMC 8 所有候选者奖项基线"
  ],
  "과거 MAA 전국 응시자 표의 Honor Roll·Distinguished Honor Roll 최저점이에요. 선택 학년의 등급이나 이번 답안의 공식 수상 여부를 판정하지 않습니다. 2021년 대회는 없어 기준선이 없습니다. 출처는 과거 MAA 보고서 통계의 2차 정리입니다.": [
    "This is the lowest score on the Honor Roll/Distinguished Honor Roll in the past MAA national test taker table. We will not determine your chosen grade level or whether this answer will receive an official award.  There is no competition in 2021 so there is no baseline. The source is the 2 difference summary of past MAA report statistics.",
    "这是历届 MAA 全国考生排行榜中荣誉榜/杰出荣誉榜的最低分。我们不会决定您选择的年级或该答案是否会获得官方奖项。 2021 中没有竞争，因此没有基线。来源为以往MAA报告统计的 2 差异汇总。"
  ],
