  "선택한 연도·시험형에 발표된 AIME 관련 점수 기준과 입력 점수를 나란히 봅니다.": [
    "View the AIME-related score standards and input scores published for the selected year/test type side by side.",
    "并排查看为所选年份/测试类型发布的 AIME 相关分数标准和输入分数。"
  ],
  "한국 AMC 8 과거 응시집단 · 같은 학년 점수 위치": [
    "Korean AMC 8 past test taker group · Same grade score location",
    "韩国AMC 8过去考生组·同年级分数位置"
  ],
  "선택 연도의 한국 AMC 응시집단 기록과 대조한 과거 자료예요. 2009·2010은 원자료의 학년별 점수 빈도에서 해당 점수보다 낮은 응시자 비율을 계산했고, 2011은 원자료에 기재된 percentile rank를 옮겼습니다. 현재 전국 기준이나 능력 등급으로 환산하지 않습니다. 표본과 계산 방식은 연도별 원자료에 연결해 표시합니다.": [
    "This is past data compared with the records of the Korean AMC test taker group for the selected year. In 2009·2010, the percentage of test takers lower than the corresponding score was calculated from the frequency of scores by grade in the original data, and in 2011, the percentile rank listed in the original data was moved. We do not currently convert to national standards or proficiency levels. Samples and calculation methods are linked to raw data by year.",
    "这是与选定年份韩国AMC考生组记录进行比较的过去数据。 2009·2010年，低于相应分数的考生百分比是根据原始数据中各年级分数出现的频率来计算的，2011年则移动了原始数据中列出的百分位数排名。我们目前不转换为国家标准或熟练程度。样本和计算方法按年份与原始数据相关联。"
  ],
