  "화면 기록 비우기": [
    "Clear screen history",
    "清除屏幕历史记录"
  ],
  "응시 지역과 입력한 응시 당시 학년은 점수 기록에 함께 저장돼요. 이름과 문항별 답은 기록하지 않습니다. 기록은 이 화면을 닫으면 사라지므로 JSON 파일로 저장해 두었다가 다시 가져오세요.": [
    "The test region and the grade you entered at the time of test are saved in the score record. Names and answers to each question are not recorded. The records will disappear when you close this screen, so save them as a JSON file and import them again.",
    "考试时输入的考试地区和成绩会保存在成绩记录中。每个问题的姓名和答案都不会被记录。当您关闭此屏幕时，这些记录将会消失，因此请将它们另存为 JSON 文件并再次导入。"
  ],
  "회차별 원점수는 서로 다른 시험 간 난도 차를 보정하지 않습니다. 공개된 같은 연도·시험형 MAA 기준점이 있는 경우에만 전체 응시자 분포의 기준선과 대조합니다. 동점자가 있어 정확한 개인 백분위가 아니며, 응시 당시 Grade는 기록 맥락일 뿐 동학년 순위나 학년별 AMC 능력 등급이 아닙니다. 수상·AIME 진출은 판정하지 않으며, 공개된 주기·지역 점수 기준을 보더라도 나이 등 다른 자격은 별도로 확인해야 합니다.": [
    "Raw scores per round do not compensate for differences in difficulty between different tests. Only if there is a publicly available MAA reference point for the same year/test type, it is compared to the baseline for the entire test taker distribution. Because there are tied scores, it is not an exact individual percentile, and the grade at the time of application is only in the context of the record and is not a rank in the same grade or AMC ability level by grade. Awards and AIME advancement are not determined, and even if you look at the published cycle and regional score standards, other qualifications such as age must be checked separately.",
    "每轮的原始分数并不能弥补不同测试之间难度的差异。仅当同一年份/测试类型有公开可用的 MAA 参考点时，才会将其与整个考生分布的基线进行比较。由于存在并列分数，因此它不是精确的个人百分位数，并且申请时的成绩仅在记录范围内，而不是同一年级中的排名或按年级的 AMC 能力水平。奖项和AIME晋级并未确定，即使查看公布的周期和地区分数标准，年龄等其他资格也必须单独检查。"
  ],
