  "2021 가을 MAA 점수보고서 이미지 ↗": [
    "2021 fall MAA score-report image ↗",
    "2021 年秋季 MAA 分数报告图片 ↗"
  ],
  "2021년 11월 가을 AMC 10 A의 MAA Contest Score Report 이미지(2022-02-06 기준)를 TestDaily 재게시본에서 확인했습니다. 평균·표준편차·상위 25·50·75% 경계와 응시자·학교·만점자 수를 Apple Vision OCR 및 이미지 대조로 전사했습니다. 이미지의 Top 2.5% 칸 96점은 당시 AIME 진출선과 같고 별도 수상 기준과 순서가 역전되어, 상위 2.5% 경계로 추가하지 않았습니다. 기존에 교차 확인한 수상 경계는 유지합니다. 보고서에 지리적 범위가 명시되지 않아 학년별·지역별 규준으로 사용하지 않습니다.": [
    "The MAA Contest Score Report image for 2021-11 fall AMC 10 A (as of 2022-02-06) was checked in TestDaily's reproduction. Mean, standard deviation, top 25/50/75% cutoffs, students, schools and perfect scores were transcribed using Apple Vision OCR and visual comparison. The image lists 96 points under Top 2.5%, matching the AIME entry line but reversing the order of the separately published award cutoffs. It is not added as a top 2.5% boundary. Previously corroborated award cutoffs are retained. The report does not specify geographic coverage, so it is not used as a grade-specific or regional norm.",
    "核对了 TestDaily 转载的 2021 年 11 月秋季 AMC 10 A 的 MAA Contest Score Report 图片（截至 2022-02-06）。通过 Apple Vision OCR 及人工对照，记录平均分、标准差、前 25/50/75% 分数线、参赛人数、学校数及满分人数。图片 Top 2.5% 栏的 96 分与当时 AIME 入围线相同，且与另行公布的奖项分数线顺序倒置，因此不作为前 2.5% 分数线添加。保留此前已交叉核对的奖项分数线。报告未注明地理范围，因此不作为特定年级或地区的常模。"
  ],
  "2021년 11월 가을 AMC 10 B의 MAA Contest Score Report 이미지(2022-02-06 기준)를 TestDaily 재게시본에서 확인했습니다. 평균·표준편차·상위 25·50·75% 경계와 응시자·학교·만점자 수를 Apple Vision OCR 및 이미지 대조로 전사했습니다. 이미지의 Top 2.5% 칸 96점은 당시 AIME 진출선과 같고 별도 수상 기준과 순서가 역전되어, 상위 2.5% 경계로 추가하지 않았습니다. 기존에 교차 확인한 수상 경계는 유지합니다. 보고서에 지리적 범위가 명시되지 않아 학년별·지역별 규준으로 사용하지 않습니다.": [
    "The MAA Contest Score Report image for 2021-11 fall AMC 10 B (as of 2022-02-06) was checked in TestDaily's reproduction. Mean, standard deviation, top 25/50/75% cutoffs, students, schools and perfect scores were transcribed using Apple Vision OCR and visual comparison. The image lists 96 points under Top 2.5%, matching the AIME entry line but reversing the order of the separately published award cutoffs. It is not added as a top 2.5% boundary. Previously corroborated award cutoffs are retained. The report does not specify geographic coverage, so it is not used as a grade-specific or regional norm.",
    "核对了 TestDaily 转载的 2021 年 11 月秋季 AMC 10 B 的 MAA Contest Score Report 图片（截至 2022-02-06）。通过 Apple Vision OCR 及人工对照，记录平均分、标准差、前 25/50/75% 分数线、参赛人数、学校数及满分人数。图片 Top 2.5% 栏的 96 分与当时 AIME 入围线相同，且与另行公布的奖项分数线顺序倒置，因此不作为前 2.5% 分数线添加。保留此前已交叉核对的奖项分数线。报告未注明地理范围，因此不作为特定年级或地区的常模。"
  ],
  "2021년 11월 가을 AMC 12 A의 MAA Contest Score Report 이미지(2022-02-06 기준)를 TestDaily 재게시본에서 확인했습니다. 평균·표준편차·상위 25·50·75% 경계와 응시자·학교·만점자 수를 Apple Vision OCR 및 이미지 대조로 전사했습니다. 이미지의 Top 5% 칸은 당시 AIME 진출선(91.5점)과 같아, 기존에 교차 확인한 상위 5% 수상선과 구분합니다. 보고서에 지리적 범위가 명시되지 않아 학년별·지역별 규준으로 사용하지 않습니다.": [
    "The MAA Contest Score Report image for 2021-11 fall AMC 12 A (as of 2022-02-06) was checked in TestDaily's reproduction. Mean, standard deviation, top 25/50/75% cutoffs, students, schools and perfect scores were transcribed using Apple Vision OCR and visual comparison. The image's Top 5% field matches the AIME entry line at the time (91.5 points), so it is kept separate from the previously corroborated top 5% award cutoff. The report does not specify geographic coverage, so it is not used as a grade-specific or regional norm.",
    "核对了 TestDaily 转载的 2021 年 11 月秋季 AMC 12 A 的 MAA Contest Score Report 图片（截至 2022-02-06）。通过 Apple Vision OCR 及人工对照，记录平均分、标准差、前 25/50/75% 分数线、参赛人数、学校数及满分人数。图片 Top 5% 栏与当时 AIME 入围线（91.5 分）相同，因此与此前已交叉核对的前 5% 奖项分数线分开。报告未注明地理范围，因此不作为特定年级或地区的常模。"
  ],
  "2021년 11월 가을 AMC 12 B의 MAA Contest Score Report 이미지(2022-02-06 기준)를 TestDaily 재게시본에서 확인했습니다. 평균·표준편차·상위 25·50·75% 경계와 응시자·학교·만점자 수를 Apple Vision OCR 및 이미지 대조로 전사했습니다. 이미지의 Top 5% 칸은 당시 AIME 진출선(84점)과 같아, 기존에 교차 확인한 상위 5% 수상선과 구분합니다. 보고서에 지리적 범위가 명시되지 않아 학년별·지역별 규준으로 사용하지 않습니다.": [
    "The MAA Contest Score Report image for 2021-11 fall AMC 12 B (as of 2022-02-06) was checked in TestDaily's reproduction. Mean, standard deviation, top 25/50/75% cutoffs, students, schools and perfect scores were transcribed using Apple Vision OCR and visual comparison. The image's Top 5% field matches the AIME entry line at the time (84 points), so it is kept separate from the previously corroborated top 5% award cutoff. The report does not specify geographic coverage, so it is not used as a grade-specific or regional norm.",
    "核对了 TestDaily 转载的 2021 年 11 月秋季 AMC 12 B 的 MAA Contest Score Report 图片（截至 2022-02-06）。通过 Apple Vision OCR 及人工对照，记录平均分、标准差、前 25/50/75% 分数线、参赛人数、学校数及满分人数。图片 Top 5% 栏与当时 AIME 入围线（84 分）相同，因此与此前已交叉核对的前 5% 奖项分数线分开。报告未注明地理范围，因此不作为特定年级或地区的常模。"
  ],
